-- 094-quiz.sql — Buzzer quiz, live, team vs team (same lobby and teams as
-- hangman/battleship, migrations 090–093). The question bank is
-- migration-095 (generated by mobile/scripts/quiz-bank.py).
--
-- Flow (all timing is the SERVER's; phones call quiz_tick() when their
-- countdown runs out and the server checks the deadline itself):
--   question  — everyone sees it; first to hit the buzzer wins the right to
--               answer (quiz_buzz takes the row lock, so the order the SERVER
--               receives the presses is the order that counts).
--   answering — only the buzzer holder answers (voice or typed), by the
--               deadline. Right → +1 to their team, reveal. Wrong or too slow
--               → they're locked out of THIS question and it reopens for the
--               others; when nobody's left, reveal with no winner.
--   reveal    — the answer is shown; after a few seconds (or "next"), the
--               next question; after the last, the game is done.
-- The accepted answers live in game_secrets until the reveal.
--
-- Public state (game_sessions.state) for the quiz:
--   phase, q (1-based), total, question {id, text, category}
--   deadline (current phase), q_deadline (the question's own clock, kept
--   while someone answers), now (server time at the last change — phones use
--   it to correct their clock)
--   buzz {email, team, at} | null, locked [emails]
--   last {email, team, text, correct, at} | null  (latest answer attempt)
--   reveal {answer, winner, by} | null
--   scores {A, B}

create table if not exists public.quiz_questions (
  id         serial primary key,
  lang       text not null check (lang in ('pt', 'en', 'es')),
  category   text not null,
  question   text not null,
  answers    text[] not null,       -- first = shown at reveal; all accepted
  difficulty int not null default 1
);
create index if not exists quiz_questions_lang_idx on public.quiz_questions (lang, category);
alter table public.quiz_questions enable row level security;
-- No policies: clients never read the bank (answers!). Definer functions do.
revoke all on table public.quiz_questions from anon, authenticated;

-- Levenshtein distance, small strings only (answers are a few words).
create or replace function public.quiz_lev(a text, b text)
returns int language plpgsql immutable as $$
declare
  la int := char_length(a); lb int := char_length(b);
  prev int[]; cur int[]; i int; j int; cost int;
begin
  if la = 0 then return lb; end if;
  if lb = 0 then return la; end if;
  prev := array(select generate_series(0, lb));
  for i in 1..la loop
    cur := array[i];
    for j in 1..lb loop
      cost := case when substr(a, i, 1) = substr(b, j, 1) then 0 else 1 end;
      cur := cur || least(prev[j + 1] + 1, cur[j] + 1, prev[j] + cost);
    end loop;
    prev := cur;
  end loop;
  return prev[lb + 1];
end $$;

-- Lowercase, accents off, only letters/digits/spaces, leading articles off:
-- "O Brasil!" → "brasil".
create or replace function public.quiz_norm(p text)
returns text language sql immutable as $$
  select btrim(regexp_replace(
           regexp_replace(
             regexp_replace(game_norm(coalesce(p, '')), '[^a-z0-9 ]', ' ', 'g'),
             '^\s*(o|a|os|as|um|uma|the|an|a|el|la|los|las|un|una)\s+', ''),
           '\s+', ' ', 'g'))
$$;

-- Right answer? Exact after normalising, or a small typo (1 edit for 4–7
-- letters, 2 for 8+; short answers must be exact).
create or replace function public.quiz_matches(p_given text, p_answers text[])
returns boolean language plpgsql immutable as $$
declare g text := quiz_norm(p_given); a text; n text; tol int;
begin
  if g = '' then return false; end if;
  foreach a in array p_answers loop
    n := quiz_norm(a);
    if n = '' then continue; end if;
    if g = n then return true; end if;
    tol := case when char_length(n) >= 8 then 2 when char_length(n) >= 4 then 1 else 0 end;
    if tol > 0 and quiz_lev(g, n) <= tol then return true; end if;
    -- "rio de janeiro" given for "rio": the answer as a whole word inside
    if char_length(n) >= 4 and (' ' || g || ' ') like ('% ' || n || ' %') then return true; end if;
  end loop;
  return false;
end $$;

-- Load question number p_q (1-based) into the state.
create or replace function public.quiz_load_question(p_session uuid, p_state jsonb, p_q int)
returns jsonb language plpgsql security definer set search_path = public as $$
declare d jsonb; qid int; qq quiz_questions; secs int := 25;
begin
  select data into d from game_secrets where session_id = p_session;
  qid := (d -> 'qids' ->> (p_q - 1))::int;
  select * into qq from quiz_questions where id = qid;
  update game_secrets set data = d || jsonb_build_object('answers', to_jsonb(qq.answers)) where session_id = p_session;
  return p_state || jsonb_build_object(
    'phase', 'question', 'q', p_q,
    'question', jsonb_build_object('id', qq.id, 'text', qq.question, 'category', qq.category),
    'deadline', now() + make_interval(secs => secs), 'q_deadline', now() + make_interval(secs => secs),
    'buzz', null, 'locked', '[]'::jsonb, 'last', null, 'reveal', null, 'now', now());
end $$;

create or replace function public.quiz_reveal(p_session uuid, p_state jsonb, p_winner text, p_by text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare ans jsonb;
begin
  select data -> 'answers' into ans from game_secrets where session_id = p_session;
  return p_state || jsonb_build_object(
    'phase', 'reveal', 'buzz', null,
    'reveal', jsonb_build_object('answer', ans ->> 0, 'winner', p_winner, 'by', p_by),
    'deadline', now() + interval '6 seconds', 'now', now());
end $$;

-- Who may still buzz on this question (active players, not locked out).
create or replace function public.quiz_left(p_session uuid, p_state jsonb)
returns int language sql stable security definer set search_path = public as $$
  select count(*)::int from game_players
   where session_id = p_session and left_at is null and team is not null
     and not (coalesce(p_state -> 'locked', '[]'::jsonb) ? email)
$$;

-- A missed answer (wrong or too slow): lock that player out of this question,
-- reopen it for the others, or reveal if nobody's left.
create or replace function public.quiz_after_miss(p_session uuid, p_state jsonb, p_email text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare st jsonb := p_state;
begin
  st := jsonb_set(st, '{locked}', coalesce(st -> 'locked', '[]'::jsonb) || to_jsonb(p_email));
  st := st || jsonb_build_object('buzz', null);
  if quiz_left(p_session, st) = 0 then
    return quiz_reveal(p_session, st, null, null);
  end if;
  -- the question's clock resumes, with at least a few seconds to buzz again
  return st || jsonb_build_object(
    'phase', 'question',
    'deadline', greatest((st ->> 'q_deadline')::timestamptz, now() + interval '6 seconds'),
    'now', now());
end $$;

-- ── lobby: game_create / game_start learn the quiz ─────────────────────────

create or replace function public.game_create(p_game text, p_mode text default 'live',
                                              p_lang text default 'pt', p_settings jsonb default '{}'::jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_hh uuid := current_household();
begin
  if v_hh is null then raise exception 'no_household'; end if;
  if p_game not in ('hangman', 'battleship', 'quiz') then raise exception 'game_unavailable'; end if;
  insert into game_sessions (household_id, game, mode, host_email, lang, settings)
  values (v_hh, p_game, coalesce(p_mode, 'live'), game_me(), coalesce(p_lang, 'pt'), coalesce(p_settings, '{}'::jsonb))
  returning id into v_id;
  insert into game_secrets (session_id) values (v_id);
  insert into game_players (session_id, email, team) values (v_id, game_me(), 'A');
  return v_id;
end $$;

create or replace function public.game_start(p_session uuid)
returns void language plpgsql security definer set search_path = public as $$
declare s game_sessions := game_lock(p_session); ta jsonb; tb jsonb; st jsonb; rounds int; qids jsonb; n int; v_lang text;
begin
  if s.host_email <> game_me() then raise exception 'not_host'; end if;
  if s.status <> 'lobby' then raise exception 'game_started'; end if;
  if exists (select 1 from game_players where session_id = p_session and left_at is null and not ready
             and email <> s.host_email) then
    raise exception 'not_ready';
  end if;
  ta := game_team(p_session, 'A'); tb := game_team(p_session, 'B');
  if jsonb_array_length(ta) = 0 or jsonb_array_length(tb) = 0 then raise exception 'need_two_teams'; end if;
  if s.game = 'battleship' then
    st := jsonb_build_object(
      'phase', 'placing', 'size', 8, 'fleet', '[4,3,3,2,2]'::jsonb,
      'order', jsonb_build_object('A', ta, 'B', tb),
      'idx', jsonb_build_object('A', 0, 'B', 0),
      'ready', jsonb_build_object('A', false, 'B', false),
      'rev', jsonb_build_object('A', 0, 'B', 0),
      'shots', jsonb_build_object('A', '[]'::jsonb, 'B', '[]'::jsonb),
      'sunk', jsonb_build_object('A', '[]'::jsonb, 'B', '[]'::jsonb),
      'scores', jsonb_build_object('A', 0, 'B', 0),
      'turn_team', null, 'shooter', null, 'last', null);
    update game_secrets set data = jsonb_build_object('fleet', jsonb_build_object('A', '[]'::jsonb, 'B', '[]'::jsonb))
     where session_id = p_session;
  elsif s.game = 'quiz' then
    n := least(greatest(coalesce((s.settings ->> 'questions')::int, 10), 5), 30);
    v_lang := case when exists (select 1 from quiz_questions where lang = s.lang) then s.lang else 'en' end;
    select coalesce(jsonb_agg(id), '[]'::jsonb) into qids
      from (select id from quiz_questions where lang = v_lang order by random() limit n) x;
    if jsonb_array_length(qids) = 0 then raise exception 'no_questions'; end if;
    update game_secrets set data = jsonb_build_object('qids', qids) where session_id = p_session;
    st := jsonb_build_object(
      'order', jsonb_build_object('A', ta, 'B', tb),
      'total', jsonb_array_length(qids),
      'scores', jsonb_build_object('A', 0, 'B', 0));
    st := quiz_load_question(p_session, st, 1);
  else
    rounds := least(greatest(coalesce((s.settings ->> 'rounds')::int, 6), 2), 20);
    rounds := rounds + rounds % 2;            -- even, so both teams guess equally
    st := jsonb_build_object(
      'order', jsonb_build_object('A', ta, 'B', tb),
      'idx', jsonb_build_object('A', 0, 'B', 0),
      'rounds', rounds, 'max_wrong', 7,
      'scores', jsonb_build_object('A', 0, 'B', 0));
    st := hangman_new_round(p_session, st, 1);
  end if;
  update game_players set ready = true where session_id = p_session and left_at is null;
  perform game_touch(p_session, st, 'playing');
end $$;

-- ── playing ────────────────────────────────────────────────────────────────

create or replace function public.quiz_buzz(p_session uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare s game_sessions := game_lock(p_session); st jsonb := s.state; v_team text := bs_my_team(p_session);
begin
  if v_team is null then raise exception 'not_player'; end if;
  if s.status <> 'playing' or st ->> 'phase' <> 'question' then
    return jsonb_build_object('first', false);       -- someone beat you to it
  end if;
  if coalesce(st -> 'locked', '[]'::jsonb) ? game_me() then raise exception 'locked_out'; end if;
  if now() > (st ->> 'deadline')::timestamptz + interval '1 second' then return jsonb_build_object('first', false); end if;
  st := st || jsonb_build_object(
    'phase', 'answering',
    'buzz', jsonb_build_object('email', game_me(), 'team', v_team, 'at', now()),
    'deadline', now() + interval '15 seconds', 'now', now());
  perform game_touch(p_session, st);
  return jsonb_build_object('first', true);
end $$;

create or replace function public.quiz_answer(p_session uuid, p_text text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare s game_sessions := game_lock(p_session); st jsonb := s.state; ans text[]; ok boolean; v_team text;
begin
  if s.status <> 'playing' or st ->> 'phase' <> 'answering' then raise exception 'not_now'; end if;
  if st -> 'buzz' ->> 'email' <> game_me() then raise exception 'not_your_turn'; end if;
  v_team := st -> 'buzz' ->> 'team';
  select array(select jsonb_array_elements_text(data -> 'answers')) into ans from game_secrets where session_id = p_session;
  -- a little grace for the network, then it's too late
  ok := now() <= (st ->> 'deadline')::timestamptz + interval '2 seconds' and quiz_matches(p_text, ans);
  st := st || jsonb_build_object('last', jsonb_build_object(
    'email', game_me(), 'team', v_team, 'text', left(btrim(coalesce(p_text, '')), 60), 'correct', ok, 'at', now()));
  if ok then
    st := jsonb_set(st, array['scores', v_team], to_jsonb(coalesce((st -> 'scores' ->> v_team)::int, 0) + 1));
    st := quiz_reveal(p_session, st, v_team, game_me());
  else
    st := quiz_after_miss(p_session, st, game_me());
  end if;
  perform game_touch(p_session, st);
  return jsonb_build_object('correct', ok);
end $$;

-- Advance a phase whose deadline passed. Anyone in the room may call it; it's
-- a no-op until the server's own clock says the time is up.
create or replace function public.quiz_tick(p_session uuid)
returns void language plpgsql security definer set search_path = public as $$
declare s game_sessions := game_lock(p_session); st jsonb := s.state; q int;
begin
  if s.status <> 'playing' or s.game <> 'quiz' then return; end if;
  if now() < (st ->> 'deadline')::timestamptz then return; end if;
  if st ->> 'phase' = 'question' then
    st := quiz_reveal(p_session, st, null, null);
  elsif st ->> 'phase' = 'answering' then
    st := st || jsonb_build_object('last', jsonb_build_object(
      'email', st -> 'buzz' ->> 'email', 'team', st -> 'buzz' ->> 'team', 'text', '', 'correct', false, 'timeout', true, 'at', now()));
    st := quiz_after_miss(p_session, st, st -> 'buzz' ->> 'email');
  else
    q := (st ->> 'q')::int;
    if q >= (st ->> 'total')::int then
      perform game_touch(p_session, st || jsonb_build_object('ended', 'finished', 'now', now()), 'done');
      return;
    end if;
    st := quiz_load_question(p_session, st, q + 1);
  end if;
  perform game_touch(p_session, st);
end $$;

-- Skip the rest of the reveal (any player).
create or replace function public.quiz_next(p_session uuid)
returns void language plpgsql security definer set search_path = public as $$
declare s game_sessions := game_lock(p_session);
begin
  if s.status <> 'playing' or s.state ->> 'phase' <> 'reveal' then return; end if;
  if bs_my_team(p_session) is null then raise exception 'not_player'; end if;
  update game_sessions set state = jsonb_set(state, '{deadline}', to_jsonb(now() - interval '1 second')) where id = p_session;
  perform quiz_tick(p_session);
end $$;

revoke all on function public.quiz_load_question(uuid, jsonb, int) from public, anon, authenticated;
revoke all on function public.quiz_reveal(uuid, jsonb, text, text) from public, anon, authenticated;
revoke all on function public.quiz_left(uuid, jsonb) from public, anon, authenticated;
revoke all on function public.quiz_after_miss(uuid, jsonb, text) from public, anon, authenticated;
revoke all on function public.game_create(text, text, text, jsonb) from public, anon;
revoke all on function public.game_start(uuid) from public, anon;
revoke all on function public.quiz_buzz(uuid) from public, anon;
revoke all on function public.quiz_answer(uuid, text) from public, anon;
revoke all on function public.quiz_tick(uuid) from public, anon;
revoke all on function public.quiz_next(uuid) from public, anon;
grant execute on function public.game_create(text, text, text, jsonb) to authenticated;
grant execute on function public.game_start(uuid) to authenticated;
grant execute on function public.quiz_buzz(uuid) to authenticated;
grant execute on function public.quiz_answer(uuid, text) to authenticated;
grant execute on function public.quiz_tick(uuid) to authenticated;
grant execute on function public.quiz_next(uuid) to authenticated;
